const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_UNIT_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const componentGroupBase = (count: number): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * COMPONENT_UNIT_PREMIUM;

const componentsBase = (items: { type: string }[]): number => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const count of counts.values()) {
    total += componentGroupBase(count);
  }
  return total;
};

const itemsBase = (items: { type: string }[]): number => {
  const mainBase = items
    .filter((item) => !COMPONENT_TYPES.has(item.type))
    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));
  return mainBase + componentsBase(components);
};

const quotePremium = (items: { type: string }[]): number => {
  const base = itemsBase(items);
  // Keep as `base + base * rate`, not `base * (1 + rate)`: the additive form
  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
};

