interface QuoteResult {
  premium: number;
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const itemPremium = (item: { type: string }): number => {
  const base = BASE_PREMIUM[item.type];
  // Keep as `base + base * rate`, not `base * (1 + rate)`: the additive form
  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
  return base + base * FIRST_INSURANCE_SURCHARGE;
};

const quotePremium = (items: { type: string }[]): number => {
  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
  return Math.ceil(itemsTotal + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

